python3 - <<'EOF'
import threading, random, time
from inventory import Inventory, MemoryStore, OutOfStock

class Jitter(MemoryStore):
    def get(self, sku):
        v = super().get(sku); time.sleep(random.uniform(0, 0.001)); return v
    def set(self, sku, qty):
        time.sleep(random.uniform(0, 0.001)); super().set(sku, qty)

for trial in range(5):
    skus = {f"SKU-{i}": 100 for i in range(4)}
    inv = Inventory(Jitter(dict(skus)))
    taken = {s: 0 for s in skus}
    guard = threading.Lock()

    def worker():
        for _ in range(40):
            s = random.choice(list(skus)); q = random.randint(1, 4)
            try:
                inv.reserve(s, q)
            except OutOfStock:
                continue
            with guard: taken[s] += q
            if random.random() < 0.4:
                inv.release(s, q)
                with guard: taken[s] -= q

    ts = [threading.Thread(target=worker) for _ in range(16)]
    for t in ts: t.start()
    for t in ts: t.join(timeout=60)
    assert not any(t.is_alive() for t in ts), "deadlock/hang"
    for s, start in skus.items():
        left = inv.available(s)
        assert left >= 0, f"{s} went negative: {left}"
        assert left + taken[s] == start, f"{s}: left={left} taken={taken[s]} start={start}"
    print(f"trial {trial}: ok, final={inv.store.snapshot()}")
print("ALL OK")
